-- 028_core_posts_block.sql
-- First-party listing block. Two modes:
--   source=archive → renders ArchiveContext supplied by the public archive pipeline (paginated, no DB query in renderer)
--   source=latest  → renders a per-node latest-posts collection populated before render (limit 1-20, no pagination)
INSERT INTO block_definitions (
    id, namespace, name, version, display_name, description, schema_json,
    renderer_type, template, styles, source, enabled, created_at, updated_at
)
VALUES (
    'core-posts-v1', 'core', 'posts', 1, 'Posts', 'Display a list of posts from the archive or latest posts.',
    '{"schemaVersion":1,"props":{"type":"object","properties":{}},"settings":{"type":"object","properties":{"source":{"type":"string","enum":["archive","latest"],"default":"archive"},"layout":{"type":"string","enum":["list","grid"],"default":"list"},"columns":{"type":"integer","enum":[1,2,3],"default":1},"showImage":{"type":"boolean","default":true},"showDate":{"type":"boolean","default":true},"showExcerpt":{"type":"boolean","default":true},"limit":{"type":"integer","default":3,"minimum":1,"maximum":20},"pagination":{"type":"boolean","default":true},"showViewAll":{"type":"boolean","default":false},"viewAllLabel":{"type":"string","default":""} }},"children":{"mode":"none"},"editor":{"category":"query","icon":"posts","fields":{"settings.source":{"label":"Source","control":"select","group":"Content"},"settings.layout":{"label":"Layout","control":"segmented","group":"Style"},"settings.columns":{"label":"Columns","control":"select","group":"Style"},"settings.showImage":{"label":"Show image","control":"checkbox","group":"Content"},"settings.showDate":{"label":"Show date","control":"checkbox","group":"Content"},"settings.showExcerpt":{"label":"Show excerpt","control":"checkbox","group":"Content"},"settings.limit":{"label":"Number of posts","control":"number","group":"Content"},"settings.pagination":{"label":"Show pagination","control":"checkbox","group":"Content"},"settings.showViewAll":{"label":"Show view all link","control":"checkbox","group":"Content"},"settings.viewAllLabel":{"label":"View all label","control":"text","group":"Content"}}}}',
    'template',
    '{{ $source := .Settings.source }}{{ if eq $source "archive" }}{{ if not .Context.Archive }}<div class="stratum-posts-placeholder">Posts archive will appear here.</div>{{ else }}{{ $entries := .Context.Archive.Entries }}{{ $settings := .Settings }}{{ if eq (len $entries) 0 }}<div class="stratum-posts-empty"><p>No posts found.</p></div>{{ else }}<section class="stratum-posts stratum-posts--{{ $settings.layout }}{{ if eq $settings.layout "grid" }} stratum-posts--cols-{{ $settings.columns }}{{ end }}">{{ range $entries }}<article class="stratum-post-card">{{ if $settings.showImage }}{{ if .FeaturedImage.Src }}<figure class="stratum-post-card__media"><img src="{{ .FeaturedImage.Src }}"{{ if .FeaturedImage.SrcSet }} srcset="{{ .FeaturedImage.SrcSet }}" sizes="(min-width: 768px) 280px, 100vw"{{ end }}{{ if .FeaturedImage.Width }} width="{{ .FeaturedImage.Width }}"{{ end }}{{ if .FeaturedImage.Height }} height="{{ .FeaturedImage.Height }}"{{ end }} alt="{{ .FeaturedImage.Alt }}" loading="lazy" decoding="async"></figure>{{ end }}{{ end }}<header class="stratum-post-card__header"><h2 class="stratum-post-card__title"><a href="{{ .URL }}">{{ .Title }}</a></h2>{{ if $settings.showDate }}{{ if .PublishedISO }}<time class="stratum-post-card__date" datetime="{{ .PublishedISO }}">{{ .PublishedAt }}</time>{{ end }}{{ end }}</header>{{ if $settings.showExcerpt }}{{ if .Excerpt }}<p class="stratum-post-card__excerpt">{{ .Excerpt }}</p>{{ end }}{{ end }}</article>{{ end }}</section>{{ if $settings.pagination }}{{ $p := $.Context.Archive.Pagination }}{{ if gt $p.TotalPages 1 }}<nav aria-label="Pagination" class="stratum-pagination">{{ if $p.PreviousURL }}<a href="{{ $p.PreviousURL }}" rel="prev">Previous</a>{{ end }}<span>Page {{ $p.Current }} of {{ $p.TotalPages }}</span>{{ if $p.NextURL }}<a href="{{ $p.NextURL }}" rel="next">Next</a>{{ end }}</nav>{{ end }}{{ end }}{{ end }}{{ end }}{{ else }}{{ $entries := index .Context.Collections .ID }}{{ $settings := .Settings }}{{ if not $entries }}<div class="stratum-posts-placeholder">No posts.</div>{{ else }}<section class="stratum-posts stratum-posts--{{ $settings.layout }}{{ if eq $settings.layout "grid" }} stratum-posts--cols-{{ $settings.columns }}{{ end }}">{{ range $entries }}<article class="stratum-post-card">{{ if $settings.showImage }}{{ if .FeaturedImage.Src }}<figure class="stratum-post-card__media"><img src="{{ .FeaturedImage.Src }}"{{ if .FeaturedImage.SrcSet }} srcset="{{ .FeaturedImage.SrcSet }}" sizes="(min-width: 768px) 280px, 100vw"{{ end }}{{ if .FeaturedImage.Width }} width="{{ .FeaturedImage.Width }}"{{ end }}{{ if .FeaturedImage.Height }} height="{{ .FeaturedImage.Height }}"{{ end }} alt="{{ .FeaturedImage.Alt }}" loading="lazy" decoding="async"></figure>{{ end }}{{ end }}<header class="stratum-post-card__header"><h2 class="stratum-post-card__title"><a href="{{ .URL }}">{{ .Title }}</a></h2>{{ if $settings.showDate }}{{ if .PublishedISO }}<time class="stratum-post-card__date" datetime="{{ .PublishedISO }}">{{ .PublishedAt }}</time>{{ end }}{{ end }}</header>{{ if $settings.showExcerpt }}{{ if .Excerpt }}<p class="stratum-post-card__excerpt">{{ .Excerpt }}</p>{{ end }}{{ end }}</article>{{ end }}</section>{{ end }}{{ if $settings.showViewAll }}{{ if $.Context.ArchiveURL }}<p class="stratum-posts-view-all"><a href="{{ $.Context.ArchiveURL }}">{{ if $settings.viewAllLabel }}{{ $settings.viewAllLabel }}{{ else }}View all posts{{ end }}</a></p>{{ end }}{{ end }}{{ end }}',
    '.stratum-posts{display:grid;gap:var(--st-space-lg)} .stratum-posts--list{grid-template-columns:1fr} .stratum-posts--grid{grid-template-columns:repeat(1,1fr)} .stratum-posts--cols-2{grid-template-columns:repeat(2,1fr)} .stratum-posts--cols-3{grid-template-columns:repeat(3,1fr)} @media(max-width: 800px){.stratum-posts--cols-2,.stratum-posts--cols-3{grid-template-columns:1fr}} .stratum-post-card{display:flex;flex-direction:column;gap:var(--st-space-sm);padding:var(--st-space-lg);border:var(--st-border-width) var(--st-border-style) var(--st-color-border);border-radius:var(--st-radius-md);background:var(--st-color-surface)} .stratum-post-card__media{margin:0} .stratum-post-card__media img{display:block;width:100%;height:auto;border-radius:var(--st-radius-sm)} .stratum-post-card__title{margin:0;font-size:1.15rem;line-height:1.3} .stratum-post-card__title a{color:var(--st-color-heading);text-decoration:none} .stratum-post-card__title a:hover{color:var(--st-color-primary);text-decoration:underline} .stratum-post-card__date{color:var(--st-color-text-muted);font-size:var(--st-small-size)} .stratum-post-card__excerpt{margin:0;color:var(--st-color-text)} .stratum-posts-placeholder{padding:var(--st-space-lg);border:1px dashed var(--st-color-border);text-align:center;color:var(--st-color-text-muted)} .stratum-posts-empty{padding:var(--st-space-xl);text-align:center;color:var(--st-color-text-muted)} .stratum-pagination{display:flex;align-items:center;justify-content:center;gap:var(--st-space-md);padding-top:var(--st-space-lg)} .stratum-pagination a{color:var(--st-color-primary);text-decoration:none} .stratum-pagination a:hover{text-decoration:underline} .stratum-posts-view-all{margin-top:var(--st-space-md);text-align:center}',
    'core', 1, unixepoch(), unixepoch()
);
